package com.modelrag.agent.trace;
import io.micrometer.core.instrument.MeterRegistry; import io.micrometer.core.instrument.Metrics; import java.util.*; import java.util.concurrent.CopyOnWriteArrayList; import java.util.concurrent.TimeUnit; import org.springframework.beans.factory.ObjectProvider; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service;
@Service public class ToolCallTracer {private final List<ToolCallTrace> local=new CopyOnWriteArrayList<>();private final ObjectProvider<JdbcTemplate> jdbc;private final MeterRegistry metrics;public ToolCallTracer(ObjectProvider<JdbcTemplate> jdbc){this(jdbc,Metrics.globalRegistry);}@Autowired public ToolCallTracer(ObjectProvider<JdbcTemplate> jdbc,MeterRegistry metrics){this.jdbc=jdbc;this.metrics=metrics;}public void record(ToolCallTrace trace){local.add(trace);metrics.counter("modelrag.tool.calls","tool",trace.toolName(),"status",trace.success()?"success":"failure").increment();metrics.timer("modelrag.tool.latency","tool",trace.toolName(),"status",trace.success()?"success":"failure").record(Math.max(0,trace.latencyMs()),TimeUnit.MILLISECONDS);JdbcTemplate db=jdbc.getIfAvailable();if(db!=null)try{db.update("INSERT INTO kb_tool_trace(trace_id,tool_name,input_params,output_result,success,error_msg,latency_ms) VALUES (?,?,CAST(? AS jsonb),CAST(? AS jsonb),?,?,?)",trace.traceId(),trace.toolName(),input(trace.params()),jsonObject(trace.output()),trace.success(),trace.error(),trace.latencyMs());}catch(Exception ignored){}}public List<ToolCallTrace> list(){JdbcTemplate db=jdbc.getIfAvailable();if(db!=null)try{return db.query("SELECT trace_id,tool_name,input_params::text,output_result::text,success,error_msg,latency_ms FROM kb_tool_trace ORDER BY id DESC LIMIT 200",(rs,n)->new ToolCallTrace(rs.getString("trace_id"),rs.getString("tool_name"),rs.getString("input_params"),rs.getString("output_result"),rs.getBoolean("success"),rs.getString("error_msg"),rs.getLong("latency_ms")));}catch(Exception ignored){}return List.copyOf(local);}private String input(String value){return "{\"query\":"+quote(value)+"}";}private String jsonObject(String value){return value==null||value.isBlank()?"{}":value.trim().startsWith("{")?value:"{\"value\":"+quote(value)+"}";}private String quote(String value){String safe=value==null?"":value;return "\""+safe.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";}}
